test('concurrent lifecycle and import-effect claims have exactly one winner',{skip:process.platform!=='linux'},async t=>{
 const {Worker}=require('node:worker_threads'),f=fixture(t),scope='isolated-lifecycle-fence-fixture';installOfflineFixture(f.p,scope);f.db.exec("INSERT INTO storage_mutations(id,mutation_type,entity_type,entity_id,trash_id,status,created_at,updated_at) VALUES('mutation','purge','output','other','trash','intent','t','t')");
 const shared=new SharedArrayBuffer(4),signal=new Int32Array(shared),modules=[require.resolve('../server/referenceLifecycleEffectFence'),require.resolve('../server/processingRepository')];
 const script=`const {workerData,parentPort}=require('node:worker_threads'),{DatabaseSync}=require('node:sqlite'),{createOfflineLifecycleFence}=require(workerData.modules[0]),{ProcessingRepository}=require(workerData.modules[1]);const db=new DatabaseSync(workerData.file);db.exec('PRAGMA foreign_keys=ON; PRAGMA busy_timeout=4000');const p=new ProcessingRepository(db);parentPort.postMessage('ready');Atomics.wait(new Int32Array(workerData.shared),0,0,5000);try{if(workerData.mode==='effect')createOfflineLifecycleFence(p,'isolated-lifecycle-fence-fixture').run('mutation',()=>null);else db.exec("INSERT INTO viewer_source_effect_claims(id,operation_id,effect_type,root_key,relative_path,dataset_relative,state,created_at) VALUES('import','op','import_cleanup','cache','item','','in_flight','t')");parentPort.postMessage('accepted')}catch(e){parentPort.postMessage(e.code==='lifecycle_effect_held'||/lifecycle effect in flight/.test(e.message)?'held':'unexpected:'+e.code+':'+e.message)}finally{db.close();parentPort.close()}`;
 const workers=[];let ready=0,timer;try{for(const mode of ['effect','import'])workers.push(new Worker(script,{eval:true,workerData:{mode,file:f.file,shared,modules}}));const answers=workers.map(worker=>new Promise((resolve,reject)=>{let answered=false;worker.on('message',message=>{if(message==='ready'){if(++ready===2){Atomics.store(signal,0,1);Atomics.notify(signal,0,2)}}else{answered=true;resolve(message)}});worker.once('error',reject);worker.once('exit',code=>{if(code!==0||!answered)reject(Error('worker exited without result'))})}));const timeout=new Promise((_,reject)=>{timer=setTimeout(()=>reject(Error('race timeout')),7000)});assert.deepEqual((await Promise.race([Promise.all(answers),timeout])).sort(),['accepted','held']);const lifecycle=f.db.prepare("SELECT COUNT(*) n FROM reference_lifecycle_effects WHERE state='in_flight'").get().n,existing=f.db.prepare("SELECT COUNT(*) n FROM viewer_source_effect_claims WHERE state='in_flight'").get().n;assert.equal(lifecycle+existing,1);}finally{clearTimeout(timer);await Promise.all(workers.map(worker=>worker.terminate()))}
});

