test('catalog cleanup process death after delete keeps claim and journal',{skip:process.platform!=='linux'},async t=>{
 const {spawn}=require('node:child_process'),f=fixture(t),scope='isolated-lifecycle-fence-fixture',target=path.join(f.root,'cleanup-source');f.db.exec('DROP TRIGGER viewer_source_binding_unavailable');installOfflineFixture(f.p,scope);insertCatalogCleanup(f);fs.writeFileSync(target,'abc');f.close();let child;
 const script=`const fs=require('node:fs'),{DatabaseSync}=require('node:sqlite'),{registerOfflineFixtureFence}=require(process.argv[1]),{ProcessingRepository}=require(process.argv[2]),{reconcileCatalogSourceCleanups}=require(process.argv[3]);const db=new DatabaseSync(process.argv[4]);db.exec('PRAGMA foreign_keys=ON');const p=new ProcessingRepository(db);registerOfflineFixtureFence(p,'isolated-lifecycle-fence-fixture');reconcileCatalogSourceCleanups(p,{async removeAdoptedSourceIfMatches(){fs.unlinkSync(process.argv[5]);process.send('deleted');Atomics.wait(new Int32Array(new SharedArrayBuffer(4)),0,0,10000);return true}})`;
 try{child=spawn(process.execPath,['-e',script,require.resolve('../server/referenceLifecycleEffectFence'),require.resolve('../server/processingRepository'),require.resolve('../server/datasetOperationWorker'),f.file,target],{stdio:['ignore','ignore','ignore','ipc']});await new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('child timeout')),5000);child.once('message',m=>{clearTimeout(timer);m==='deleted'?resolve():reject(Error('bad marker'))});child.once('error',e=>{clearTimeout(timer);reject(e)});child.once('exit',()=>{clearTimeout(timer);reject(Error('early child exit'))})});const exited=new Promise(resolve=>child.once('exit',resolve));child.kill('SIGKILL');await exited;child=null;f.reopen();assert.equal(f.db.prepare('SELECT state FROM reference_catalog_cleanup_effects').get().state,'in_flight');assert.ok(JSON.parse(f.db.prepare("SELECT payload_json FROM dataset_operations WHERE id='catalog'").get().payload_json).sourceCleanup);assert.throws(()=>prepare(f.p,request(f)),{code:'source_binding_unavailable'});
 }finally{if(child&&child.exitCode===null&&child.signalCode===null){const exited=new Promise(resolve=>child.once('exit',resolve));child.kill('SIGKILL');await exited}try{fs.unlinkSync(target)}catch(e){if(e.code!=='ENOENT')throw e}}
});

